def _git(*args: str, timeout: int = 30) -> subprocess.CompletedProcess[str]:
    try:
        return subprocess.run(
            ["git", *args],
            cwd=str(REPO_ROOT),
            check=False,
            capture_output=True,
            text=True,
            timeout=timeout,
            env={"GIT_TERMINAL_PROMPT": "0"},
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime git unavailable",
        ) from exc


def _converge_development_if_safe() -> dict[str, str]:
    fetch = _git("fetch", "--quiet", "origin", DEV_BRANCH, timeout=90)
    if fetch.returncode != 0:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime development fetch failed",
        )

    branch = _git("branch", "--show-current").stdout.strip()
    local = _git("rev-parse", "HEAD").stdout.strip()
    remote = _git("rev-parse", f"origin/{DEV_BRANCH}").stdout.strip()
    if not _SHA_RE.fullmatch(local) or not _SHA_RE.fullmatch(remote):
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime development sha invalid",
        )
    if local == remote:
        return {"state": "ALIGNED", "local_sha": local, "remote_sha": remote}
    if branch != DEV_BRANCH:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail=f"worker runtime convergence blocked: wrong branch {branch}",
        )
    ancestor = _git("merge-base", "--is-ancestor", local, remote)
    if ancestor.returncode != 0:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="worker runtime convergence blocked: non-fast-forward",
        )
    dirty = _git("status", "--porcelain=v1", "--untracked-files=all")
    if dirty.returncode != 0:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime worktree status unavailable",
        )
    if dirty.stdout.strip():
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="worker runtime convergence blocked: local worktree dirty",
        )
    ff = _git("merge", "--ff-only", f"origin/{DEV_BRANCH}", timeout=120)
    if ff.returncode != 0:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime fast-forward failed",
        )
    new_head = _git("rev-parse", "HEAD").stdout.strip()
    if new_head != remote:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="worker runtime fast-forward verification failed",
        )
    return {"state": "FF_APPLIED", "local_sha": local, "remote_sha": remote, "new_sha": new_head}


